<script>
import { payloadHelper } from '~/helpers/payload.helper';

export default {
    data() {
        return {
            isLoading: true,
            foodSustainabiltyData: {}
        }
    },
    mounted() {
        this.checkAuth().then((status) => {
            if (status == 500) {
                this.$nuxt.error({ statusCode: 500, message: 'err message' })
            } else {
                this.$store.dispatch('notification/clear');
                this.fetchDataFoodSustainabilty();
            }
        });
    },
    methods: {
        async checkAuth() {
            return this.$userCheckAuth.checkAuth(this.moduleId);
        },
        async fetchDataFoodSustainabilty() {
            let normalParam = payloadHelper.normalParam('');
            return this.$FoodSustainabilityRepo.getByParam(normalParam)
                .then(response => {
                    if (response.status === 'OK') {
                        this.foodSustainabiltyData = response.result[0];
                    }
                })
                .finally(() => {
                    console.log('foodSustainabiltyData completed');
                    this.isLoading = false;
                })
                .catch(error => {
                    console.error('Error fetching food sustainability index data:', error);
                });
        },
        getBadgeClass(keterangan) {
            return keterangan === 'up' ? 'badge bg-light text-danger' : 'badge bg-light text-success';
        },
        getIconClass(keterangan) {
            return keterangan === 'down' ? 'ri-arrow-down-line' : 'ri-arrow-up-line';
        },
        formattedMtMValue() {
            return this.foodSustainabiltyData.indeks_ketahanan_pangan
                ? this.foodSustainabiltyData.indeks_ketahanan_pangan
                : '0,00';
        },
    },
}
</script>